\label{def}
    Let $p\in(1,\infty]$, $q\in[1,\infty]$, $M>0$ and $\phi\in \mathcal{I}_o(0,M)$. 
If $p<\infty$, then we set $w\in A_p(\mathbb{R}^d)$ and if $p=\infty$, then we set $L_p(\mathbb{R}^d,w\,\mathrm{d}x):=L_{\infty}(\mathbb{R}^d)$. 
    \begin{enumerate}[(i)]
    \item
    The space $B_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)$ is defined by
    $$
    B_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x):=\{f\in\mathcal{S}'(\mathbb{R}^d):\|f\|_{B_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}<\infty\},
    $$
    where the norm $\|f\|_{B_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}$ is defined by
    \begin{eqnarray*}
    \|S_0f\|_{L_p(\mathbb{R}^d,w\,\mathrm{d}x)}
    +\left\{
    \begin{array}{ll}
    \Big(\sum_{j=1}^{\infty}\phi(2^{j})^q\|\Delta_jf\|_{L_p(\mathbb{R}^d,w\,\mathrm{d}x)}^q\Big)^{1/q}, &q<\infty,\\
    \sup_{j\in\mathbb{N}}\phi(2^j)\|\Delta_jf\|_{L_p(\mathbb{R}^d,w\,\mathrm{d}x)}, &q=\infty.
    \end{array}
    \right.
    \end{eqnarray*}
    We also define the homogeneous Besov norm
    \begin{eqnarray*}
    \|f\|_{\mathring{B}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}
    :=\left\{
    \begin{array}{ll}
    \left(\sum_{j\in\mathbb{Z}}\phi(2^j)^q\|\Delta_jf\|_{L_p(\mathbb{R},w\,\mathrm{d}x)}^q\right)^{1/q}, &q<\infty,\\
    \sup_{j\in\mathbb{Z}}\phi(2^j)\|\Delta_jf\|_{L_p(\mathbb{R}^d,w\,\mathrm{d}x)}, &q=\infty.
    \end{array}
    \right.
    \end{eqnarray*}

    \item
    The space $F_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)$ is defined by
    $$
    F_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x):=\{f\in\mathcal{S}'(\mathbb{R}^d):\|f\|_{F_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}<\infty\},
    $$
    where the norm $\|f\|_{F_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}$ is defined by
    \begin{eqnarray*}
    \|S_0f\|_{L_p(\mathbb{R}^d,w\,\mathrm{d}x)}
    + \left\{
    \begin{array}{ll}
    \Big\|\Big(\sum_{j=1}^{\infty}\phi(2^{j})^q|\Delta_jf|^q\Big)^{1/q}\Big\|_{L_p(\mathbb{R}^d,w\,\mathrm{d}x)}, &q<\infty,\\
    \Big\|\sup_{j\in\mathbb{N}}\phi(2^j)|\Delta_jf|\Big\|_{L_p(\mathbb{R}^d,w\,\mathrm{d}x)}, &q=\infty.
    \end{array}
     \right.
    \end{eqnarray*}
    We also define the homogeneous Triebel-Lizorkin norm
    \begin{eqnarray*}
    \|f\|_{\mathring{F}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}
    :=\left\{
    \begin{array}{ll}
    \left\|\left(\sum_{j\in\mathbb{Z}}\phi(2^j)^q|\Delta_jf|^q\right)^{1/q}\right\|_{L_p(\mathbb{R},w\,\mathrm{d}x)}, &q<\infty,\\
    \left\|\sup_{j\in\mathbb{Z}}\phi(2^j)|\Delta_jf|\right\|_{L_p(\mathbb{R}^d,w\,\mathrm{d}x)}, &q=\infty.
    \end{array}
    \right.
    \end{eqnarray*}
    \end{enumerate}

\label{homo}
If all of conditions in Theorem \ref{thm_lp_diff_equiv} hold, then for $f\in X_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)$,
		\begin{align*}
			\|f\|_{\mathring{X}_{p,q}^\phi(\mathbb{R}^d,w\,\mathrm{d} x)}\simeq \|f\|_{\mathring{\mathscr{X}}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}.
   \end{align*}
Here, $(X,\mathscr{X})=(B,\mathscr{B})$, $(F,\mathscr{F})$.

\label{rem:mainthm}
$(i)$ If $w\equiv1$, then
\begin{align}\label{230612535}
R_{w}=1,\quad \Gamma_w=\infty.
\end{align}
Thus,
$$
\frac{d}{p}\left(R_w+\frac{1}{\Gamma_w}-1\right)=0\quad \text{and}\quad \frac{dR_w}{p}=\frac{d}{p}\,.
$$
Hence Theorem~\ref{thm_lp_diff_equiv}-$(i)$ contains non-weighted characterizations introduced in \cite{triebel1983theory}.
Similarly, it can be easily checked that Theorem~\ref{thm_lp_diff_equiv}-$(ii)$ also contains non-weighted characterizations introduced in \cite{triebel1983theory}.

It is worth noting that any weights satisfying \eqref{230612535} suggest the largest class of $\phi$ for which Theorem~\ref{thm_lp_diff_equiv} holds.
One of sufficient conditions for \eqref{230612535} is  $w\in A_1\cap RH_\infty$, which means that
\begin{equation}
\label{25.11.04.13.10}
	w(x) \simeq \mathcal{M} w(x)\simeq \inf_{ Q\ni x}-\hspace{-0.40cm}\int_{\mathcal{Q}}w(y)\,\mathrm{d}y, \quad \forall x\in\mathbb{R}^d.
\end{equation}
Moreover, it is proved in \cite[Theorem 5.1]{Kin_Sh2014} that \eqref{25.11.04.13.10} holds if and only if $\log w\in \overline{L^{\infty}(\mathbb{R}^d)}\subseteq \mathrm{BMO}(\mathbb{R}^d)$.

$(ii)$ If $\phi \not\in \mathcal{I}_o \left(\frac{d}{p}\left(R_w+\frac{1}{\Gamma_w}-1\right),M \right)$, then there is a counter example for Theorem~\ref{thm_lp_diff_equiv}-$(i)$.
That is, there is a certain weight $w$ such that if $\phi\in \mathcal{I}_o \left( 0,\frac{d}{p}\left(R_w+\frac{1}{\Gamma_w}-1\right) \right)$, then 
\begin{align*}
    \mathscr{B}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)\subsetneq \mathcal{B}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)\subsetneq B_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x).
\end{align*}
Indeed, let $d=1$, $p,q\in(1,\infty)$, $\alpha\in(0,p-1)$, and $w(x)=|x|^{\alpha}$. Then, it follows that $w$ is in $A_p(\mathbb{R})$, $R_{w}=1+\alpha$, and $1/\Gamma_w=0$.
Consequently,
$$
\frac{d}{p}\left(R_{w}+\frac{1}{\Gamma_w}-1\right)=\frac{\alpha}{p}.
$$
Assume that $\phi(\lambda)=\lambda^{\theta}$, where $\theta\leq \alpha/p$, and $f_0 \in C_c^{\infty}(\mathbb{R})$, which satisfies two conditions:
\begin{itemize}
\item $|f_0(x)|\geq1$ for $x\in(-1,1)$,
\item $f_0(x)=0$ for $x\geq2$ or $x\leq-2$.
\end{itemize}
We then have that $f_0$ is in the space $\mathcal{B}_{p,q}^{\phi}(\mathbb{R},w\,\mathrm{d}x)$ and $\phi$ belongs to $\mathcal{I}_o(0,\alpha/p)$.
Using Proposition \ref{prop_wBesov_equiv} and Lemma \ref{23.02.08.15.58}, we can deduce that
$$
\mathcal{B}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)\subseteq B_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x),
$$
thus, $f_0\in B_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)$.

First, we verify that
\begin{equation}
	\label{eq230928_01}
\mathscr{B}_{p,q}^{\phi}(\mathbb{R},w\,\mathrm{d}x)\subsetneq \mathcal{B}_{p,q}^{\phi}(\mathbb{R},w\,\mathrm{d}x).
\end{equation}
Since for $h>4$,
$$
\|f_0(\cdot+h)-f_0\|_{L_p(\mathbb{R},w\,\mathrm{d}x)}^p\geq\int_{-\infty}^{\infty}|f_0(x+h)|^p|x|^{\alpha}\mathrm{d}x\geq \int_{-1}^{1}|x-h|^{\alpha}\mathrm{d}x\geq Nh^{\alpha}
$$
we have
$$
\int_{\mathbb{R}}\frac{\|f_0(\cdot+h)-f_0\|_{L_p(\mathbb{R},w\,\mathrm{d}x)}^q}{|h|^{1+q\theta}}\mathrm{d}h\geq \int_{4}^{\infty}h^{q(\frac{\alpha}{p}-\theta)-1}\mathrm{d}h=+\infty,
$$
and this implies \eqref{eq230928_01}.

To demonstrate that
$$
\mathcal{B}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)\subsetneq B_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x),
$$
we need to prove that the inclusion mapping $I:\mathcal{B}_{p,q}^{\phi}(\mathbb{R}^d,w\mathrm{d}x)\to B_{p,q}^{\phi}(\mathbb{R}^d,w\mathrm{d}x)$ is not surjective.
To establish this, we assume, for the sake of contradiction, that $I$ is surjective.
Then, by Proposition \ref{prop_wBesov_equiv} and Lemma \ref{23.02.08.15.58}, $I$ is bounded linear and bijective.
Hence \cite[Theorem 5.10]{rudin2006real}, we have
\begin{align}
\label{23.06.14.16.17}
    \|g\|_{\mathcal{B}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}\lesssim \|I(g)\|_{B_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}=\|g\|_{B_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}, \,\, \forall g\in \mathcal{B}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x).
\end{align}
However, under the assumption of Theorem \ref{thm_lp_diff_equiv}-$(i)$, \eqref{23.06.14.16.17} fails.
To verify this, put $f_n(x):=2^{n/p}f_0(2^nx)$.
Then for $n\geq3$,
\begin{align}
\label{23.06.14.18.51}
    \int_{|h|\leq1}\frac{\|f_n(\cdot+h)-f_n\|_{L_p(\mathbb{R},w\,\mathrm{d}x)}^q}{|h|^{1+q\theta}}\mathrm{d}h= 2^{qn\left(\theta-\alpha/p\right)}\int_{|h|\leq2^n}\frac{\|f_0(\cdot+h)-f_0\|_{L_p(\mathbb{R},w\,\mathrm{d}x)}^q}{|h|^{1+q\theta}}\mathrm{d}h.
\end{align}
Moreover,
\begin{equation}
\label{23.06.14.18.52}
    \begin{gathered}
        \|f_n\|_{L_p(\mathbb{R},w\,\mathrm{d}x)}=2^{-n\alpha/p}\|f_0\|_{L_p(\mathbb{R},w\,\mathrm{d}x)},\\
        \|f_n\|_{\mathring{B}_{p,q}^{\phi}(\mathbb{R},w\,\mathrm{d}x)}:=\left(\sum_{j\in\mathbb{Z}}\phi(2^j)^q\|\Delta_jf_n\|_{L_p(\mathbb{R},w\,\mathrm{d}x)}^q\right)^{1/q} =2^{n\left(\theta-\alpha/p\right)}\|f_0\|_{\mathring{B}_{p,q}^{\phi}(\mathbb{R},w\,\mathrm{d}x)}.
    \end{gathered}
\end{equation}
Therefore, by \eqref{23.06.14.16.17}, \eqref{23.06.14.18.51} and \eqref{23.06.14.18.52}
\begin{align*}
    &2^{-n\alpha/p}\|f_0\|_{L_p(\mathbb{R},w\,\mathrm{d}x)}+2^{n\left(\theta-\alpha/p\right)}\left(\int_{4}^{2^n}|h|^{q(\alpha/p-\theta)-1}\mathrm{d}h\right)^{1/q}\\
    &\leq 2^{-\frac{n\alpha}{p}}\|f_0\|_{L_p(\mathbb{R},w\,\mathrm{d}x)}+2^{n\left(\theta-\alpha/p\right)}\left(\int_{|h|\leq2^n}\frac{\|f_0(\cdot+h)-f_0\|_{L_p(\mathbb{R},w\,\mathrm{d}x)}^q}{|h|^{1+q\theta}}\mathrm{d}h\right)^{1/q}\\
    &=\|f_n\|_{\mathcal{B}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}\\
    &\lesssim \|f_n\|_{B_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}\simeq 2^{-n\alpha/p}\|f_0\|_{L_p(\mathbb{R},w\,\mathrm{d}x)}+2^{n\left(\theta-\alpha/p\right)}\|f_0\|_{\mathring{B}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)}.
\end{align*}
The last equivalence follows from Proposition \ref{prop_wBesov_equiv}.
This certainly implies
$$
+\infty=\lim_{n\to\infty}\left(\int_{4}^{2^n}|h|^{q(\alpha/p-\theta)-1}\mathrm{d}h\right)^{1/q}\lesssim\|f_0\|_{\mathring{B}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)},
$$
which contradicts the fact that $f_0$ is in $\mathring{B}_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)$.

\label{poly}
	Let $p,\,q\in (1,\infty)$, {\color{blue}$L>0$} and $\phi\in\mathcal{I}_o(0,L)$.
 For any polynomial $P$,
	\begin{align}\label{230714638}	\|P\|_{\mathring{\mathscr{X}}_{p,q}^\phi(\mathbb{R}^d)}=0\quad\text{if}\,\,\,\,\deg P<L\quad\text{and}\quad \|P\|_{\mathring{\mathscr{X}}_{p,q}^\phi(\mathbb{R}^d)}=\infty\quad\text{if}\,\,\,\,\deg P\geq L.
	\end{align}

The first three assertions are in \cite[Corollary 7.2.6, Lemma 9.2.1, Theorem 7.2.2]{grafakos2014classical}, respectively. 
The fourth assertion can be found in \cite[Lemma 3]{G1973}.
Thus, we only prove the last assertion.
Let $w$ be of class $RH_s(\mathbb{R}^d)$.
Then 
\begin{align}\label{ineq_RH}
	\Big(\frac{1}{|\mathcal{Q}|}\int_{\mathcal{Q}} w(x)^s~\mathrm{d}x\Big)^{1/s} \leq [w]_{RH_s} \frac{1}{|\mathcal{Q}|}\int_\mathcal{Q} w(x)~\mathrm{d}x.
\end{align}
By making use of \eqref{ineq_RH}, it follows that for a subset $S$ of a cube $\mathcal{Q}$
\begin{align*}
    w(S) 
    = \int_\mathcal{Q} \mathbbm{1}_S(x) w(x)~\mathrm{d}x
    \leq \Big(\int_\mathcal{Q} w(x)^s~\mathrm{d}x\Big)^{\frac{1}{s}} |S|^{1-1/s}
    \leq [w]_{RH_s} w(\mathcal{Q}) \left(\frac{|S|}{|\mathcal{Q}|}\right)^{1-1/s}.
\end{align*}

\label{23.05.25.13.12}
Let $a,b\in\mathbb{R}$ with $a < b$ and $\phi\in \mathcal{I}(a,b)$.
    \begin{enumerate}[(i)]
        \item For $\alpha\in\mathbb{R}$, $t^\alpha \phi(t) \in \mathcal{I}(a+\alpha, b+\alpha)$.
        \item For $\alpha\geq0$, $\phi(t^\alpha), \phi(t)^\alpha \in \mathcal{I}(\alpha a, \alpha b)$.
        \item For $\alpha \leq 0$, $\phi(t^\alpha), \phi(t)^\alpha \in \mathcal{I}(\alpha b, \alpha a)$.
        \item For $a<c$, $b>d$, $\mathcal{I}(c,d)\subset \mathcal{I}_{o}(a,b)$ and
        \begin{align*}
		\bigcup_{a< c,\,b>d} \mathcal{I}(c, d) = \mathcal{I}_o(a, b).
        \end{align*}
        \item For $\phi\in\mathcal{I}_{o}(a,b)$, there exists $\varepsilon = \varepsilon(\phi) >0$ such that
        \begin{align}\label{w scaling}
		\lambda^{a+\varepsilon}\lesssim \frac{\phi(\lambda t)}{\phi(t)} \lesssim \lambda^{b - \varepsilon},
	    \end{align}
	     for $t \in \mathbb{R}_+$ and $\lambda \geq 1$.
        \item For $\phi \in \mathcal{I}_o(a, b)$, the assertions (i)--(iii) hold for $\mathcal{I}_{o}(a,b)$ instead of $ \mathcal{I}(a,b)$.

    \end{enumerate}

\label{230610919}
    If $w\in A_p(\mathbb{R}^d)$, then for any $r\in[1,R_{w,p})$ and $s\in[1,\Gamma_w)$, we have 
    \begin{align}\label{smf_wlog_ubound}
        \| \mathcal{M}^z \|_{L_p(w) \to L_p(w)} 
        \lesssim N(w)
        (1+|z|)^{\frac{d}{p}\left(\frac{p}{r} + \frac{1}{s}-1\right)},
    \end{align}
where $N(w)=[w]_{A_p}^{\frac{1}{p-1}}[w]_{A_{p/r}}^{\frac{1}{p}} [w]_{RH_s}^{\frac{1}{p}}\geq 1$.
The implicit constant depends only on $d,\,p,\,s$, and $r$.

Let $f\in L_p(w)$.
We only prove for the case $z=\vec{n}\in\mathbb{Z}^d$ and $\vec{n}\not=0$, since generalization for $z\in\mathbb{R}^d$ follows from the argument in \cite[Lemma 2.9]{Heo_Hong_Yang2020}.
Let $\mathbb{Q}^\lambda$ be a collection of all dyadic cubes $Q$ such that
\begin{itemize}
	\item $Q$ is maximal with respect to inclusion;
	\item $\frac{1}{|Q|}\int_{Q}|f(y)|~\mathrm{d}y > \lambda$.
\end{itemize}
Then it follows that
\begin{align}
	\bigcup_{Q \in \mathbb{Q}^\lambda} Q = \{ x\in\mathbb{R}^d : \mathcal{M}(f)(x) > \lambda\}.
\end{align}
Moreover, for $m=[\log_2|\vec{n}|]+1$ and each dyadic cube $Q\in \mathbb{Q}^\lambda$, the cubes 
$$
Q^i=2^{-i}\ell(Q)\vec{n}+Q\,\,\,\,(i=0,\,\dots,\,m-1)\quad\text{and}\quad Q^m=3Q
$$ satisfy
\begin{align}\label{condi_Q}
    \begin{split}
        (a)\,\, &\text{$\ell(Q^i)\leq 3\ell(Q)$};\\
        (b)\,\, &\text{$Q^i \subset 2^{-i+3}|\vec{n}|Q$};\\
        (c)\,\, &\{x\in\mathbb{R}^d : \mathcal{M}^{\vec{n}}(f)(x)>\lambda\} \subset \bigcup\limits_{Q \in \mathbb{Q}^\lambda} \left(Q^0 \cup\cdots\cup Q^{m}\right)
    \end{split}
\end{align}
(see the proofs of Lemmas 2.6 and 2.9 in \cite{Heo_Hong_Yang2020}).
Here, $aQ$ ($a\in\mathbb{R}_+$) denotes a cube whose side length is $a$ times of $\ell(Q)$ with the same center as $Q$.
From \eqref{condi_Q}, we have
\begin{align*}
w(Q^i)&=\frac{w(Q^i)}{w(2^{-i+3}|\vec{n}|Q)}\frac{w(2^{-i+3}|\vec{n}|Q)}{w(Q)}w(Q)\\
&\leq [w]_{RH_s}\left(\frac{|Q^i|}{(2^{-i+3}|\vec{n}|)^d|Q|}\right)^{1-1/s}[w]_{A_{p/r}}\left(\frac{(2^{-i+3}|\vec{n}|)^d|Q|}{|Q|}\right)^{p/r}w(Q)\\
&\lesssim_d [w]_{A_{p/r}}[w]_{RH_s}(2^{-i+3}|\vec{n}|)^{\left(\frac{p}{r} + \frac{1}{s}-1\right)d}w(Q)
\end{align*}
(see Propositions~\ref{23.04.21.16.12}.$(ii)$ and $(v)$) and
\begin{equation}\label{ineq_230321_2038}
	\begin{alignedat}{2}
	&&&w\Big(\{x\in\mathbb{R}^d : \mathcal{M}^{\vec{n}}(f)(x)>\lambda\}\Big)\\
	&\leq &&\sum_{Q \in \mathbb{Q}^\lambda}\sum_{i=0}^m w(Q^i)\\
	&\lesssim_d&&[w]_{A_{p/r}}[w]_{RH_s}\left(\sum_{i=0}^m2^{(-l+3)(p+1/s-1)d}\right)|\vec{n}|^{\left(\frac{p}{r} + \frac{1}{s}-1\right)d}\sum_{Q \in \mathbb{Q}_n^\lambda}^m w(Q)\\
	&\lesssim_{d,p,r,s}&&[w]_{A_{p/r}}[w]_{RH_s}\cdot |\vec{n}|^{\left(\frac{p}{r} + \frac{1}{s}-1\right)d}\cdot w\left( \{ x\in\mathbb{R}^d : \mathcal{M}(f)(x) > \lambda\} \right)\,.
	\end{alignedat}
\end{equation}
Thus we have
\begin{align*}
    \|\mathcal{M}^{\vec{n}}f\|_{L_p(w)}^p
    &= p\int_0^\infty \lambda^{p-1} w\left(\{\mathcal{M}^{\vec{n}}f>\lambda\}\right)~\mathrm{d}\lambda\\
    &\lesssim p [w]_{A_{p/r}}[w]_{RH_s}|{\vec{n}}|^{\left(\frac{p}{r} + \frac{1}{s}-1\right)d}\int_0^\infty \lambda^{p-1} w\left(\{\mathcal{M} f>\lambda\}\right)~\mathrm{d}\lambda\\
    &= [w]_{A_{p/r}} [w]_{RH_s}|\vec{n}|^{\left(\frac{p}{r} + \frac{1}{s}-1\right)d} \|\mathcal{M} f\|_{L_p(w)}^p
\end{align*}
and this means that
\begin{alignat*}{2}
	\| \mathcal{M}^{\vec{n}} \|_{L_p(w) \to L_p(w)} &\lesssim_{d,p,r,s} &&[w]_{A_{p/r}}^{\frac{1}{p}} [w]_{RH_s}^{\frac{1}{p}}|\vec{n}|^{\frac{d}{p}\left(\frac{p}{r} + \frac{1}{s}-1\right)}\| \mathcal{M} \|_{L_p(w) \to L_p(w)}\\
	&\lesssim_{d,p}&&[w]_{A_p}^{\frac{1}{p-1}}[w]_{A_{p/r}}^{\frac{1}{p}} [w]_{RH_s}^{\frac{1}{p}}|\vec{n}|^{\frac{d}{p}\left(\frac{p}{r} + \frac{1}{s}-1\right)}
\end{alignat*}
(for the last inequality, see \cite[Theorem 9.1.9]{grafakos2014modern}).
For $z\in\mathbb{R}^d$, it is known in the proof of \cite[Lemma 2.9]{Heo_Hong_Yang2020} that for $z=\vec{n}+z_0$, $z_0\in[0,1]^d$
$$
    \mathcal{M}^z(f)(x) \lesssim \sum_{i=1}^{2^d} \mathcal{M}^{\vec{n}+\vec{n}_i}(f)(x),
$$
where $\vec{n}_i \in \mathbb{Z}^d$ and each component of $\vec{n}_i$ takes on values of either $0$ or $1$.
Therefore we have
\begin{align*}
    \| \mathcal{M}^z \|_{L_p(w) \to L_p(w)} \lesssim_{d,p,r,s} [w]_{A_p}^{\frac{1}{p-1}}[w]_{A_{p/r}}^{\frac{1}{p}} [w]_{RH_s}^{\frac{1}{p}} (1+|z|)^{\frac{d}{p}\left(\frac{p}{r} + \frac{1}{s}-1\right)}.
\end{align*}
The proposition is proved.

\label{lem_wlog_besov}
Let $L\in\mathbb{N}$, $w\in A_{p}(\mathbb{R}^d)$ and $f\in L_p(\mathbb{R}^d, w\,\mathrm{d}x)$.
Then for any $\rho\in\mathbb{R}^d$, $r\in[1,R_{w,p})$, and $s\in[1,\Gamma_w)$,
         \begin{align*}
            \| \mathcal{D}_{\rho}^L S_0f\|_{L_p(w)} 
            &\lesssim N(w) \min(|\rho|,1)^L\big(1+|\rho|\big)^{\frac{d}{p}\left(\frac{p}{r}+\frac{1}{s}-1\right)}\|S_0 f\|_{L_p(w)},\\
         	\| \mathcal{D}_{\rho}^L\Delta_jf\|_{L_p(w)} 
            &\lesssim N(w)\min(2^j|\rho|,1)^L\big(1+2^j|\rho|\big)^{\frac{d}{p}\left(\frac{p}{r}+\frac{1}{s}-1\right)} \|\Delta_j f\|_{L_p(w)},
         \end{align*}
         where $N(w)$ is the constant in Proposition~\ref{230610919}.
         The implicit constants depend only on $d,p$ and $L$.

The proof of the first inequality is nothing but taking $j=0$ in the
	proof of the second inequality.
	Hence we only consider $\mathcal{D}_\rho^L \Delta_j f$.
	For a smooth function $F$ on $\mathbb{R}^d$, the fundamental theorem of calculus implies that
	\begin{equation}\label{ineq_230322_1843}
		\begin{aligned}
			\mathcal{D}_\rho F (x) &=F(x+\rho)-F(x)\\
			&= \int_0^1\left( \rho_1D_{x_1}F+\cdots \rho_dD_{x_d}F\right) \left( x+t \rho \right)\,\mathrm{d} t\\
			&\leq |\rho|\sum_{i=1}^d\int_0^1\big|\big(D_{x_i}F\big)(x+t\rho)\big|\,\mathrm{d} t\,.
		\end{aligned}
	\end{equation}
By using \eqref{ineq_230322_1843} inductively, we obtain
\begin{equation}
\label{230610943}
\begin{aligned}
&\mathcal{D}_\rho^L \Delta_jf (x)\\
&\lesssim_{d,L} |\rho|^L\sum_{\substack{\alpha=(\alpha_1,\ldots,\alpha_d)\in \mathbb{N}_0^d\\\alpha_1+\cdots+\alpha_d=L}}\int_{[0,1]^L}\big|\big(D_x^\alpha \Delta_jf\big)\big(x+(t_1+\cdots+t_L)\rho\big)\big|\,\mathrm{d}t_1\cdots\mathrm{d}t_L\,,
\end{aligned}
\end{equation}
where $D_x^\alpha=\big(D_{x_1}\big)^{\alpha_1}\cdots \big(D_{x_d}\big)^{\alpha_d}$.

Take a Schwartz function $\phi\in \mathcal{S}(\mathbb{R}^d)$ such that $\widehat{\phi}\equiv 1$ on $\mathrm{supp} (\widehat{\psi})$, and denote $\phi_{2^j}(x):=2^{jd}\phi(2^jx)$.
Then, we have $\widehat{\psi_j} = \widehat{\phi_{2^j}}\,\widehat{\psi_j}$, 
which implies that $\Delta_j f = \phi_{2^j} * (\Delta_j f)$.
Note that for $\alpha$ in \eqref{230610943},
$$
D_{x}^{\alpha}\Delta_jf = \big(D_{x}^{\alpha}\phi_{2^j}\big)\ast \Delta_jf\quad\text{and}\quad D_{x}^{\alpha}\phi_{2^j}=2^{jL} 2^{jd} \big(D_{x}^\alpha \phi\big)(2^j \,\cdot\,).
$$
Since $D_x^\alpha\phi\in\mathcal{S}(\mathbb{R}^d)$, we obtain that 
$$
\big|D_x^\alpha\phi\big(x)|\lesssim_{\alpha,d}(1+|x|)^{-100 d}
$$
and that for any $\rho\in\mathbb{R}^d$,
	\begin{equation*}
	\begin{alignedat}{2}
		|D_{x}^{\alpha}\Delta_jf(x + \rho)| 
		&\lesssim_{\alpha,d}\,&& 2^{jL}\int_{\mathbb{R}^d} |\Delta_jf(y)| \frac{2^{jd}}{(1+2^j|x-y+\rho|)^{100d}} ~\mathrm{d}y\\
		&\lesssim_d &&2^{jL}\sum_{\vec{n}\in\mathbb{Z}^d} (1+|\vec{n}|)^{-100d} 2^{jd} \int_{(x+\rho + 2^{-j} \vec{n})+I_j} |\Delta_jf(y)|~\mathrm{d}y\\
		&\leq &&2^{jL}\sum_{\vec{n}\in\mathbb{Z}^d} (1+|\vec{n}|)^{-100d} \sum_{k=1}^{N_d}2^{jd} \int_{(\rho + 2^{-j} \vec{n})+I_{j,k}} |\Delta_jf(y)|~\mathrm{d}y,
	\end{alignedat}
\end{equation*}
	where $I_j = [0, 2^{-j}]^d$ and $\{I_{j,k}\}_{k=1,\dots,N_d}$ is a collection of all dyadic cubes such that $l(I_{j,k})=l(I_j)$ and $(x+I_j)\cap I_{j,k}\neq \emptyset$.
	Thus we have
$$
		|D_{x}^{\alpha}\Delta_jf(x + \rho)| 
		\lesssim_{\alpha,d}
		2^{jL}\sum_{\vec{n}\in\mathbb{Z}^d} (1+|\vec{n}|)^{-100d} \mathcal{M}^{2^j \rho+\vec{n}}\left(\Delta_jf\right)(x)
$$
and by Proposition~\ref{230610919}, we obtain
\begin{align}\label{ineq_230322_1845}
	\|D_{x}^{\alpha}\Delta_jf(\,\cdot + \rho)\|_{L_p(w)} \lesssim N(w) 
	2^{jL}\sum_{\vec{n}\in\mathbb{Z}^d} (1+|\vec{n}|)^{-100d} (1+2^j|\rho|+|\vec{n}|)^{\frac{d}{r}+\frac{d}{ps}-\frac{d}{p}}\|\Delta_jf\|_{L_p(w)}\,.
\end{align}
	With help of \eqref{230610943} and \eqref{ineq_230322_1845}, it follows that
	\begin{equation}\label{ineq_230321_2126}
		\begin{aligned}
			\|\mathcal{D}_{\rho}^L \Delta_jf\|_{L_p(w)}&\lesssim  
			N(w)\big(2^{j}|\rho|\big)^L\sum_{\vec{n}\in\mathbb{Z}^d}
			\frac{(1+ |\vec{n}|+2^j|L\rho|)^{\frac{d}{r} + \frac{d}{ps}-\frac{d}{p}}}{(1+|\vec{n}|)^{100d}}
			\|\Delta_j f\|_{L_p(w)}\\
			& \lesssim N(w)\big(2^{j}|\rho|\big)^L\big(1+2^j|\rho|\big)^{\frac{d}{r} + \frac{d}{ps}-\frac{d}{p}}\|\Delta_j f\|_{L_p(w)},
		\end{aligned}
	\end{equation}
and note that $\frac{d}{r} + \frac{d}{ps}-\frac{d}{p}\leq d$.

On the other hand, we have that
	\begin{align*}
		\mathcal{D}_\rho^L\Delta_j f (x)=\sum_{k=0}^{L}\binom{L}{k}(-1)^{L-k}\Delta_jf(x+k\rho).
	\end{align*}
	For each term in the above, one can check from \eqref{ineq_230322_1845} that
	\begin{align*}
		\|\Delta_jf(x+k\rho)\|_{L_p(w)} &\lesssim N(w) (1+ 2^{j}k|\rho|)^{\frac{d}{r} + \frac{d}{ps}-\frac{d}{p}} \|\Delta_j f\|_{L_p(w)}\,,
	\end{align*}
	which implies 
	\begin{align}\label{ineq_wlog2}
		\|\mathcal{D}_{\rho}^L\Delta_jf\|_{L_p(w)} \lesssim N(w) (1+ 2^{j}|\rho|)^{\frac{d}{r} + \frac{d}{ps}-\frac{d}{p}} \|\Delta_j f\|_{L_p(w)}.
	\end{align}
	The lemma is proved by a combination of \eqref{ineq_230321_2126} and \eqref{ineq_wlog2}.

