\label{prop_wBesov_equiv}
Let $\phi\in\mathcal{I}_o(0,M)$ and $L\geq M$ be a natural number. 
\begin{enumerate}
\item (Weighted Besov space) For $p\in(1,\infty]$, $q\in[1,\infty]$, we have
\begin{align*}
	\|f\|_{B_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)} \simeq B_i\quad \text{for}\quad i=0,1,2,3,4,5.
\end{align*}
\item (Weighted Triebel-Lizorkin space) For $p,q\in(1,\infty)$, we have
\begin{align*}
	\|f\|_{F_{p,q}^{\phi}(\mathbb{R}^d,w\,\mathrm{d}x)} \simeq F_i\quad \text{for} \quad i=0,1,2,3,4,5.
\end{align*}
\end{enumerate}

\label{23.02.08.15.58}
$X_3 \lesssim \|f\|_{\mathcal{X}_{p,q}^{\phi}(w)}$.
That is, $\mathcal{X}_{p,q}^{\phi}(w)$ is continuously embedded into the space equipped with the norm $X_3$.

\label{23.02.09.14.46}
$ \mathcal{X}_1 \lesssim X_5$.
That is, the space equipped with the norm $X_5$ is continuously embedded into the space equipped with the norm $\mathcal{X}_0$.

Recall that
\begin{align*}
	B_2 &= \|f\|_{L_p(w)} + \Big( \int_0^\infty \phi(t^{-1})^q \left\| \psi_{\frac{1}{t}} \ast f \right\|_{L_p(w)}^q ~\frac{\mathrm{d}t}{t}\Big)^{\frac{1}{q}},\\
	F_2 &= \|f\|_{L_p(w)} + \Big\| \Big( \int_0^\infty \phi(t^{-1})^q \left| \psi_{\frac{1}{t}} \ast f \right|^q ~\frac{\mathrm{d}t}{t}\Big)^{\frac{1}{q}}\Big\|_{L_p(w)}.
\end{align*}

\textbf{Step 1.} $\|f\|_{X_{p,q}^{\phi}(w)}\lesssim X_2$.

Since $|S_0f|\leq N\mathcal{M}(f)$, it suffices to prove
\begin{align*}
	\Big(\sum_{j\in\mathbb{Z}} \phi(2^j)^q\|\Delta_jf\|_{L_p(w)}^q \Big)^{\frac{1}{q}}
	&\lesssim \Big( \int_0^\infty \phi(t^{-1})^q \left\| \psi_{\frac{1}{t}} \ast f \right\|_{L_p(w)}^q ~\frac{\mathrm{d}t}{t}\Big)^{\frac{1}{q}}\\
       \Big\| \Big( \sum_{j\in\mathbb{Z}} \phi(2^j)^q \left| \Delta_jf \right|^q\Big)^{\frac{1}{q}} \Big\|_{L_p(w)}
       &\lesssim \Big\| \Big( \int_0^\infty \phi(t^{-1})^q \left| \psi_{\frac{1}{t}} \ast f \right|^q ~\frac{\mathrm{d}t}{t}\Big)^{\frac{1}{q}}\Big\|_{L_p(w)}.
\end{align*}
First we prove for $X=B$.
To do so, we define 
\begin{align}\label{ineq_230315_1543}
	\Psi_j:=\sum_{i=-1}^{2}\int_{2^{j-1}}^{2^j}\psi_{2^it}\frac{\mathrm{d}t}{t}\quad
	\text{so that} \quad
	\Delta_j f = N \Delta_j(\Psi_j \ast f).
\end{align}
Indeed, \eqref{ineq_230315_1543} follows from $\Delta_jf=\Delta_j \left( \left(\psi_{t/2}+\psi_{t}+\psi_{2t}+\psi_{4t} \right)\ast  f \right)$ for all $t\in[2^{j-1},2^{j})$ and $\int_{2^{j-1}}^{2^j} t^{-1}~\mathrm{d}t = N$.
By making use of \eqref{ineq_230315_1543}, we have for $p\in(1,\infty],q\in[1,\infty)$,
\begin{align*}
    \sum_{j=1}^{\infty}\phi(2^{j})^q\|\Delta_jf\|_{L_p(w)}^q&\leq N\sum_{j=1}^{\infty}\phi(2^{j})^q\|\Psi_j\ast f\|_{L_p(w)}^q\\
    &\leq N\sum_{j=1}^{\infty}\int_{2^{j-1}}^{2^{j}}\phi(2^{j})^q\sum_{i=-1}^2\|\psi_{2^it}\ast f\|_{L_p(w)}^q\frac{\mathrm{d}t}{t}\\
    &\leq N\sum_{i=-1}^2\int_{1}^{\infty}\phi(2^{i}t)^q\|\psi_{2^it}\ast f\|_{L_p(w)}^q\frac{\mathrm{d}t}{t}\\
    &\leq 4N\int_{1}^{\infty}\phi(t)^q\|\psi_t\ast f\|_{L_p(w)}^q\frac{\mathrm{d}t}{t}.
\end{align*}
Note that the last line equals to 
\begin{align}
	4N\int_{0}^{1}\phi(t^{-1})^q\|\psi_{1/t}\ast f\|_{L_p(w)}^q\frac{\mathrm{d}t}{t}.
\end{align}
If $q=\infty$, then
$$
	\phi(2^j)\|\Delta_jf\|_{L_p(w)}=\phi(2^j)\|\psi_{2^j}\ast f\|_{L_p(w)}\leq \sup_{t>0}\phi(t^{-1})\|\psi_{1/t}\ast f\|_{L_p(w)},
$$
and this implies that
$$
	\|f\|_{B_{p,q}^\phi(w)} \lesssim B_2,\quad \forall p\in(1,\infty],q\in[1,\infty].
$$

For $X=F$, we have
\begin{align*}
    \Big( \sum_{j\geq1} \phi(2^j)^q |\Delta_jf|^q \Big)^{\frac{1}{q}} 
    \lesssim \Big( \sum_{j\geq1} \phi(2^j)^q |\mathcal{M} (\Phi_j \ast f )|^q \Big)^{\frac{1}{q}}.
\end{align*}
By Lemma \ref{23.01.31.17.22},
\begin{align*}
    \Big\| \Big( \sum_{j\geq1} \phi(2^j)^q |\mathcal{M} (\Phi_j \ast f )|^q \Big)^{\frac{1}{q}}  \Big\|_{L_p(w)}
    \lesssim \Big\| \Big( \sum_{j\geq1} \phi(2^j)^q |\Phi_j \ast f |^q \Big)^{\frac{1}{q}}  \Big\|_{L_p(w)}.
\end{align*}
Note that 
\begin{align*}
    \sum_{j\geq 1} \phi(2^j)^q|\Phi_j\ast f|^q
    &\lesssim \sum_{j\geq 1}\sum_{i=-1}^{2}\int_{2^{j-1}}^{2^{j}}\phi(2^j)^q|\psi_{2^it}\ast f|^q\frac{\mathrm{d}t}{t}\\
    &\leq \sum_{j=1}^{\infty}\sum_{i=-1}^{2}\int_{2^{j-1}}^{2^{j}}\phi(2^it)^q|\psi_{2^it}\ast f|^q\frac{\mathrm{d}t}{t}\\
    &\lesssim \int_{0}^{\infty}\phi(t)^q|\psi_{t}\ast f|^q\frac{\mathrm{d}t}{t}.
\end{align*}
Hence we have
$$
	\|f\|_{F_{p,q}^{\phi}(w)}\lesssim F_2.
$$

\textbf{Step 2.} $X_2 \lesssim \|f\|_{X_{p,q}^{\phi}(w)}$.

By Lemma \ref{Lp_bound}, it suffices to prove
\begin{align*}
	\Big( \int_0^\infty \phi(t^{-1})^q \left\| \psi_{\frac{1}{t}} \ast f \right\|_{L_p(w)}^q ~\frac{\mathrm{d}t}{t}\Big)^{\frac{1}{q}}
	&\lesssim \|f\|_{B_{p,q}^{\phi}(w)},\\
	\Big\| \Big( \int_0^\infty \phi(t^{-1})^q \left| \psi_{\frac{1}{t}} \ast f \right|^q ~\frac{\mathrm{d}t}{t}\Big)^{\frac{1}{q}}\Big\|_{L_p(w)}
	&\lesssim \|f\|_{F_{p,q}^{\phi}(w)}.
\end{align*}
We begin with $X=B$. 
If $t<1/4$, then $\psi_t\ast f=\psi_t\ast S_0f$, hence we have
\begin{align*}
	\int_0^{1/4}\phi(t)^{q}\left\|\psi_t\ast f\right\|_{L_p(w)}^q\frac{\mathrm{d}t}{t}
	&\leq N\|S_0f\|_{L_p(w)}^q\int_0^{1/4}\phi(t)^{q}\frac{\mathrm{d}t}{t}\\
	&=N\|S_0f\|_{L_p(w)}^q,\quad \forall q\in[1,\infty)
\end{align*}
and
$$
	\sup_{t\in(0,1/4)}\phi(t)\|\psi_t\ast f\|_{L_p(w)}\leq \sup_{t\in(0,1/4)}\phi(t)\|S_0f\|_{L_p(w)}\leq N\|S_0f\|_{L_p(w)}.
$$
Then, we make use of the following equality
$$
\psi_t\ast f=\psi_t\ast(\Delta_{j-1}f+\Delta_{j}f+\Delta_{j+1}f+\Delta_{j+2}f),\quad \forall t\in[2^{j-1},2^j), j\geq-1
$$
to obtain that for $q\in[1,\infty)$
\begin{align*}
    \int_{1/4}^{\infty}\phi(t)^q\left\|\psi_t\ast f\right\|_{L_p(w)}^q\frac{\mathrm{d}t}{t}
    &=\sum_{j=-1}^{\infty}\int_{2^{j-1}}^{2^{j}}\phi(t)^q\sum_{i=-1}^2\|\Delta_{j+i}f\|_{L_p(w)}^q\frac{\mathrm{d}t}{t}\\
    &\leq N\|f\|_{B_{p,q}^{\phi}(\mathbb{R}^d,w,\mathrm{d}x)}^q.
\end{align*}
For $q=\infty$, we have
\begin{align*}
	\phi(t)\|\psi_t\ast f\|_{L_p(w)}
	&\leq \phi(t)\sum_{i=-1}^2\|\Delta_{j+i}f\|_{L_p(w)}\\
	&\leq N\|f\|_{B_{p,\infty}^{\phi}(\mathbb{R}^d,w,\mathrm{d}x)},\quad \forall t\in[2^{j-1},2^j),j\geq-1.
\end{align*}
This certainly implies that
$$
	B_2 \lesssim \|f\|_{B_{p,q}^\phi(w)},\quad \forall p\in(1,\infty],q\in[1,\infty].
$$

For $X=F$, we proceed in a similar manner.
Note that
$$
\begin{gathered}
|\psi_t\ast f|\leq N\mathcal{M}(S_0f),\quad \forall t\in(0,1/4),\\
