Then we apply \eqref{ineq_230317_1503} to the last line of \eqref{ineq_230317_1511}.
\begin{equation}\label{ineq_230317_1517}
\begin{aligned}
	 &\Big\| \Big( \sum_{j\in\mathbb{Z}} \phi(2^{j})^q \left|\psi_{2^{j}}^L \ast f\right|^q \Big)^\frac{1}{q} \Big\|_{L_p(w)}\\
	 &= \Big\| \Big( \sum_{j\in\mathbb{Z}} \phi(2^{j})^q \Big|  \psi_{2^{j}
  }^L \ast \sum_{-2\leq i\leq 2} \int_{2^{j-1}}^{2^j} \psi_{2^i t}^L\ast f ~\frac{\mathrm{d}t}{t} \Big|^q \Big)^\frac{1}{q} \Big\|_{L_p(w)}\\
