  \end{aligned}
\end{equation}
By Lemma~\ref{23.01.31.17.22} again to the last line of \eqref{ineq_230317_1517}, it follows that
\begin{equation}\label{ineq_230317_1525}
\begin{aligned}
	&\Big\| \Big( \sum_{j\in\mathbb{Z}} \phi(2^{j})^q \Big|  \mathcal{M}\Big(  \int_{2^{j-1}}^{2^j} \psi_{t}^L\ast f ~\frac{\mathrm{d}t}{t}\Big) \Big|^q \Big)^\frac{1}{q} \Big\|_{L_p(w)}\\
	 &\lesssim \Big\| \Big( \sum_{j\in\mathbb{Z}} \phi(2^{j})^q \Big|  \int_{2^{j-1}}^{2^j} \psi_{t}^L\ast f ~\frac{\mathrm{d}t}{t}\Big|^q \Big)^\frac{1}{q} \Big\|_{L_p(w)}\\
	 &\leq \Big\| \Big( \sum_{j\in\mathbb{Z}} \int_{2^{j-1}}^{2^j} \phi(t)^q  \left| \psi_{t}^L\ast f \right|^q~\frac{\mathrm{d}t}{t} \Big)^\frac{1}{q} \Big\|_{L_p(w)}\\
	 &=  \Big\| \Big( \int_0^\infty \phi(t^{-1})^q  \left| \psi_{\frac{1}{t}}^L\ast f \right|^q~\frac{\mathrm{d}t}{t} \Big)^\frac{1}{q} \Big\|_{L_p(w)},
\end{aligned}
\end{equation}
where the last equality follows from summation over $j\in\mathbb{Z}$ and the change of variable $t\to t^{-1}$.
Combining \eqref{ineq_230317_1511}, \eqref{ineq_230317_1517}, \eqref{ineq_230317_1525}, we conclude
$$
	F_2 \lesssim F_3.
$$
\end{enumerate}

The converse direction, verifying $X_3 \lesssim X_2$, is rather simpler than showing $X_2 \lesssim X_3$.
Let $|f|_X$ denote $|f|_B$, $|f|_F$ with $|f|_B = \|f\|_{L_p(w)}$ and  $|f|_F = |f(x)|$.
Then we have
\begin{align*}
\int_0^\infty \phi(t^{-1})^q |\psi_{\frac{1}{t}}^L \ast f |_X^q ~\frac{\mathrm{d}t}{t}
&\leq \sum_{j=1}^L \binom{L}{j} \int_0^\infty \phi(t^{-1})^q |\psi_{\frac{1}{jt}} \ast f |_X^q ~\frac{\mathrm{d}t}{t}\\
&\lesssim_L \int_0^\infty \phi(t^{-1})^q |\psi_{\frac{1}{t}} \ast f |_X^q ~\frac{\mathrm{d}t}{t}.
\end{align*}
Hence, we easily obtain $X_3 \lesssim X_2$.
The lemma is proved.

Due to similarity, we only prove for $X_4$.
Recall that
\begin{align}
	B_4 &=  \|M_{d/r}^{0,*}f\|_{L_p(w)} + \left( \sum_{j\geq1} \phi(2^j)^q \| M_{j,d/r}^{*}f \|_{L_p(w)}^q\right)^{1/q},\\
	F_4 &= \|M_{d/r}^{0,*}f\|_{L_p(w)} + \left\| \left( \sum_{j\geq1} \phi(2^j)^q | M_{j,d/r}^{*}f |^q\right)^{1/q} \right\|_{L_p(w)}.
\end{align}
By Lemma \ref{22.12.28.17.28} ($2$),
$$
	|\Delta_jf(x)|\leq M_{j,d/r}^{*}f(x),\quad |S_0f(x)|\leq M_{d/r}^{0,*}f(x)\quad \text{for all $x\in\mathbb{R}^d$}
$$
and this certainly implies that
$$
	\|f\|_{X_{p,q}^{\phi}(w)}\lesssim X_4.
$$


For the converse inequality, note that $w\in A_p(\mathbb{R}^d)$, for $r\in(0,R_{w,p})$, the weight $w\in A_{p/r}(\mathbb{R}^d)$. 
Then we apply Lemma \ref{22.12.28.17.28} ($3$) to obtain
\begin{align*}
    \|f\|_{X_{p,q}^{\phi,4}(w)}
    \lesssim &\|\mathcal{M}(|S_0f|^{r})^{1/r}\|_{L_p(w)}
    \\
    &\quad+\left\{ 
    \begin{array}{ll}
        \left( \sum_{j\geq1} \phi(2^j)^q \| \mathcal{M}(|\Delta_j f|^r)^{\frac{1}{r}} \|_{L_p(w)}^q\right)^{1/q}, &X=B\\
        \left\| \left( \sum_{j\geq1} \phi(2^j)^q | \mathcal{M}(|\Delta_j f|^r)^{\frac{1}{r}} |^q\right)^{1/q} \right\|_{L_p(w)}, &X=F.
    \end{array}
    \right.
\end{align*}
Thus we have 
$$
	X_4 \lesssim \|f\|_{X_{p,q}^{\phi}(w)}.
$$
The lemma is proved.

If $\gamma\in[0,\infty)$, $p,q\in(1,\infty)$, $w\in A_p(\mathbb{R}^d)$, $\tilde{w}\in A_{q}(\mathbb{R})$, and
$$
\phi(\lambda):=\lambda^{\gamma+2}\left(\int_{0}^{\lambda^{-2}}\tilde{w}(t)\mathrm{d}t\right)^{1/q}\in\mathcal{I}_o\left(\frac{d}{p}\left(R_w+\frac{1}{\Gamma_w}-1\right),M\right)
$$
for some positive integer $M > \frac{d}{p}\left(R_w+\frac{1}{\Gamma_w}-1\right)$, then for a given initial data $u_0\in\mathscr{B}_{p,q}^{\phi}(w)$, there exists a unique solution $u\in L_q((0,T),\tilde{w}\,\mathrm{d}t;H_p^{\gamma+2}(w))$ to the equation
\begin{align*}
\begin{cases}
\partial_tu(t,x)=\Delta u(t,x),\quad &(t,x)\in(0,T)\times\mathbb{R}^d,\\
u(0,x)=u_0(x),\quad &x\in\mathbb{R}^d
\end{cases}
\end{align*}
with the estimate
\begin{equation*} \left(\int_{0}^T\left(\|u(t,\cdot)\|_{H_p^{\gamma}(w)}+\|u_{xx}(t,\cdot)\|_{H_p^{\gamma}(w)}+\|\partial_tu\|_{H_p^{\gamma}(w)}\right)^q\tilde{w}(t)\mathrm{d}t\right)^{1/q}\lesssim\|u_0\|_{\mathscr{B}_{p,q}^{\phi}(w)}.
\end{equation*}
Moreover,
\begin{equation*} \left(\int_{0}^T\left(\|u_{xx}(t,\cdot)\|_{H_p^{\gamma}(w)}+\|\partial_tu\|_{H_p^{\gamma}(w)}\right)^q\tilde{w}(t)\mathrm{d}t\right)^{1/q}\lesssim\|u_0\|_{\mathring{\mathscr{B}}_{p,q}^{\phi}(w)}.
\end{equation*}

\label{23.05.29.13.46}
    Let $\alpha\in(0,1]$, $p,q\in(1,\infty)$, $w\in A_p(\mathbb{R}^d)$. and $\tilde{w}\in A_q(\mathbb{R})$. Suppose that
    $$
    \tilde{W}_{\alpha}(\lambda):=\left(\int_{0}^{\lambda}\tilde{w}(t^{1/\alpha})\mathrm{d}t\right)^{1/q}\in \mathcal{I}_o\left(0,1\right),
    $$
    \begin{equation}
    \label{25.11.03.19.52}
    \phi(\lambda):=\lambda^2\tilde{W}_{\alpha}(\lambda^{-2})\in\mathcal{I}_o\left(\frac{d}{p}\left(R_w+\frac{1}{\Gamma_w}-1\right),M\right),
    \end{equation}
    for some positive integer $M > \frac{d}{p}\left(R_w+\frac{1}{\Gamma_w}-1\right)$.
    Then for a given initial data $u_0\in \mathscr{B}_{p,q}^{\phi}(w)$, there exists a unique solution $u\in L_q((0,T),\tilde{w}\,\mathrm{d}t;H_p^2(w))$ to the equation
    \begin{align}
    \label{23.05.29.13.09}
        \begin{cases}
        \partial_t^{\alpha}u(t,x)=\Delta u(t,x),\quad &(t,x)\in(0,T)\times\mathbb{R}^d,\\
        u(0,x)=u_0(x),\quad &x\in\mathbb{R}^d
    \end{cases}
    \end{align}
    with the estimate
    \begin{equation}
        \label{23.05.29.13.11}
        \||u|+|u_{xx}|+|\partial_t^{\alpha}u|\|_{L_q((0,T),\tilde{w}\,\mathrm{d}t;L_p(w))}\lesssim\|u_0\|_{\mathscr{B}_{p,q}^{\phi}(w)}.
    \end{equation}
